//! The interpolator (the `SMC_Interpolator` analogue): consumes a planned
//! geometry queue and produces per-cycle path setpoints.
//!
//! Motion along the path parameter `s` is generated by rsruckig as a 1-DoF
//! jerk-limited profile per segment: current `(s, ṡ, s̈)` → `(L, v_exit, 0)`,
//! where `v_exit` comes from the look-ahead plan, so segments blend without
//! stopping. Trajectories are computed offline per segment
//! ([`rsruckig`]'s `calculate`) and sampled with `Trajectory::at_time`
//! using our own time bookkeeping, so segment boundaries do not suffer
//! cycle-quantization errors. Feed-override changes, pause (override 0 /
//! halt) and resume simply retarget the profile from the current state.

use crate::error::CncError;
use crate::geometry::{GeoElem, GeoMove, Segment, SyncEvent};
use crate::lookahead::{LookAhead, PlannedSegment};
use crate::queue::GeoQueue;
use crate::types::{PathLimits, PathPoint};
use rsruckig::prelude::*;

/// Standstill threshold for the path velocity.
const EPS_V: f64 = 1e-9;
/// Override values below this snap to 0 (a slower crawl would produce
/// trajectory durations beyond rsruckig's supported range).
const MIN_OVERRIDE: f64 = 0.005;

/// Interpolator state (the `SMC_INT_STATUS` analogue).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum IplState {
    /// No program loaded.
    #[default]
    Idle,
    /// Interpolating a move segment.
    Running,
    /// Executing a G4 dwell.
    Dwelling,
    /// Decelerating to standstill (override → 0 or halt).
    Pausing,
    /// At standstill; waiting for override > 0 / resume.
    Paused,
    /// Single-step mode: stopped at a segment boundary, waiting for `step()`.
    StepHold,
    /// Program complete.
    Finished,
}

/// Per-cycle interpolator output.
#[derive(Debug, Clone)]
pub struct IplOutput {
    pub state: IplState,
    /// Position on the programmed path.
    pub path_position: PathPoint,
    /// Unit tangent of the path at the current point (zero for pure aux moves).
    pub path_tangent: PathPoint,
    /// Path speed ṡ ≥ 0.
    pub path_velocity: f64,
    /// Tangential path acceleration s̈.
    pub path_acceleration: f64,
    /// Auxiliary axis positions.
    pub aux: Vec<f64>,
    /// Auxiliary axis velocities.
    pub aux_velocity: Vec<f64>,
    /// Synchronized events crossed during this cycle.
    pub events: Vec<SyncEvent>,
    /// Source line of the current (or last) move.
    pub src_line: usize,
    /// Object number of the current (or last) move.
    pub obj_no: u32,
    /// Completed path length, including progress into the current segment.
    pub s_total: f64,
    /// Fraction of the total program path length completed (0..1).
    pub progress: f64,
}

pub struct Interpolator {
    limits: PathLimits,
    lookahead: LookAhead,
    aux_max_velocity: Vec<f64>,
    cycle_time: f64,

    queue: Vec<GeoElem>,
    plan: Vec<PlannedSegment>,
    cursor: usize,
    plan_pos: usize,
    total_length: f64,

    otg: Ruckig<1, ThrowErrorHandler>,
    input: InputParameter<1>,
    traj: Trajectory<1>,
    traj_time: f64,
    traj_override: f64,
    /// Effective exit velocity the current trajectory was planned for.
    planned_v_exit: f64,
    /// Coordinate rebase for a stop trajectory that crosses segment boundaries.
    stop_s_offset: f64,

    state: IplState,
    s_local: f64,
    v_s: f64,
    a_s: f64,
    s_done: f64,
    dwell_remaining: f64,
    override_pct: f64,
    halted: bool,
    single_step: bool,
    step_pending: bool,
    time: f64,

    point: PathPoint,
    tangent: PathPoint,
    aux_now: Vec<f64>,
    aux_vel_now: Vec<f64>,
    pending_events: Vec<SyncEvent>,
    last_src_line: usize,
    last_obj_no: u32,
}

impl Interpolator {
    pub fn new(
        limits: PathLimits,
        lookahead: LookAhead,
        aux_max_velocity: Vec<f64>,
        cycle_time: f64,
    ) -> Self {
        Self {
            limits,
            lookahead,
            aux_max_velocity,
            cycle_time,
            queue: Vec::new(),
            plan: Vec::new(),
            cursor: 0,
            plan_pos: 0,
            total_length: 0.0,
            otg: Ruckig::new(None, cycle_time),
            input: InputParameter::new(None),
            traj: Trajectory::new(None),
            traj_time: 0.0,
            traj_override: 1.0,
            planned_v_exit: 0.0,
            stop_s_offset: 0.0,
            state: IplState::Idle,
            s_local: 0.0,
            v_s: 0.0,
            a_s: 0.0,
            s_done: 0.0,
            dwell_remaining: 0.0,
            override_pct: 1.0,
            halted: false,
            single_step: false,
            step_pending: false,
            time: 0.0,
            point: [0.0; 3],
            tangent: [0.0; 3],
            aux_now: Vec::new(),
            aux_vel_now: Vec::new(),
            pending_events: Vec::new(),
            last_src_line: 0,
            last_obj_no: 0,
        }
    }

    /// Load a (preprocessed) queue and run the look-ahead plan over it.
    /// Resets all runtime state; interpolation starts from rest at the
    /// first move's start point.
    pub fn load(&mut self, queue: GeoQueue) -> Result<(), CncError> {
        self.plan = self.lookahead.plan(&queue, &self.limits, &self.aux_max_velocity);
        self.queue = queue.into_iter().collect();
        self.total_length = self.plan.iter().map(|p| p.length).sum();
        self.cursor = 0;
        self.plan_pos = 0;
        self.s_local = 0.0;
        self.v_s = 0.0;
        self.a_s = 0.0;
        self.s_done = 0.0;
        self.time = 0.0;
        self.traj_time = 0.0;
        self.step_pending = false;
        self.pending_events.clear();
        // Initial pose from the first move
        if let Some(mv) = self.queue.iter().find_map(|e| match e {
            GeoElem::Move(m) => Some(m),
            _ => None,
        }) {
            self.point = mv.geo.start();
            self.tangent = [0.0; 3];
            self.aux_now = mv.aux_start.clone();
            self.aux_vel_now = vec![0.0; mv.aux_start.len()];
        } else {
            self.point = [0.0; 3];
            self.tangent = [0.0; 3];
        }
        self.state = IplState::Running; // enter_next refines this
        self.enter_next(self.effective_override())?;
        Ok(())
    }

    /// Feed override factor (1.0 = 100%). Values below 0.5% snap to 0,
    /// which decelerates to a pause; raising it again resumes.
    pub fn set_override(&mut self, factor: f64) {
        self.override_pct = if factor < MIN_OVERRIDE { 0.0 } else { factor };
    }

    pub fn override_factor(&self) -> f64 {
        self.override_pct
    }

    /// Decelerate to standstill and hold (independent of the override value).
    pub fn halt(&mut self) {
        self.halted = true;
    }

    /// Release a halt.
    pub fn resume(&mut self) {
        self.halted = false;
    }

    /// In single-step mode every segment ends at standstill and the
    /// interpolator waits for [`step`](Self::step) before continuing.
    pub fn set_single_step(&mut self, on: bool) {
        self.single_step = on;
    }

    /// Execute the next segment while in [`IplState::StepHold`].
    pub fn step(&mut self) {
        self.step_pending = true;
    }

    pub fn state(&self) -> IplState {
        self.state
    }

    pub fn cycle_time(&self) -> f64 {
        self.cycle_time
    }

    fn effective_override(&self) -> f64 {
        if self.halted {
            0.0
        } else {
            self.override_pct
        }
    }

    /// Advance one control cycle.
    pub fn cycle(&mut self) -> Result<IplOutput, CncError> {
        self.time += self.cycle_time;
        let ovr = self.effective_override();

        match self.state {
            IplState::Idle | IplState::Finished => {}
            IplState::Paused => {
                if ovr > 0.0 {
                    // Resume: replan from standstill. The cursor may still sit
                    // on a move boundary that was never planned (paused there).
                    if self.current_move().is_some() {
                        self.plan_move_traj(ovr)?;
                        self.state = IplState::Running;
                    } else {
                        self.enter_next(ovr)?;
                    }
                }
            }
            IplState::StepHold => {
                if self.step_pending && ovr > 0.0 {
                    self.step_pending = false;
                    self.plan_move_traj(ovr)?;
                    self.state = IplState::Running;
                }
            }
            IplState::Dwelling => {
                if ovr > 0.0 {
                    self.dwell_remaining -= self.cycle_time;
                    if self.dwell_remaining <= 0.0 {
                        self.enter_next(ovr)?;
                    }
                }
            }
            IplState::Running | IplState::Pausing => {}
        }

        if self.state == IplState::Running {
            if ovr <= 0.0 {
                if self.v_s <= EPS_V {
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    self.state = IplState::Paused;
                } else {
                    self.plan_stop_traj()?;
                    self.state = IplState::Pausing;
                }
            } else if (ovr - self.traj_override).abs() > 1e-9 {
                // Override changed mid-segment: retarget from the current state
                self.plan_move_traj(ovr)?;
            }
        }

        match self.state {
            IplState::Running => self.step_running(ovr)?,
            IplState::Pausing => self.step_pausing()?,
            _ => {}
        }

        Ok(self.make_output())
    }

    // --- internals -------------------------------------------------------

    fn current_move(&self) -> Option<&GeoMove> {
        match self.queue.get(self.cursor) {
            Some(GeoElem::Move(m)) => Some(m),
            _ => None,
        }
    }

    fn current_plan(&self) -> &PlannedSegment {
        &self.plan[self.plan_pos]
    }

    /// Enter the next queue element(s): fire events, start dwells, or plan
    /// the next move. `self.cursor` must point at the element to enter.
    fn enter_next(&mut self, ovr: f64) -> Result<(), CncError> {
        loop {
            match self.queue.get(self.cursor) {
                None => {
                    self.state = IplState::Finished;
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    return Ok(());
                }
                Some(GeoElem::Event(e)) => {
                    self.pending_events.push(e.clone());
                    self.last_src_line = e.src_line;
                    self.cursor += 1;
                }
                Some(GeoElem::Dwell { seconds, src_line }) => {
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    self.dwell_remaining = *seconds;
                    self.last_src_line = *src_line;
                    self.cursor += 1;
                    self.state = IplState::Dwelling;
                    return Ok(());
                }
                Some(GeoElem::Move(_)) => {
                    while self.plan[self.plan_pos].queue_index < self.cursor {
                        self.plan_pos += 1;
                    }
                    debug_assert_eq!(self.plan[self.plan_pos].queue_index, self.cursor);
                    self.s_local = 0.0;
                    self.a_s = 0.0;
                    if self.single_step {
                        self.v_s = 0.0;
                        self.state = IplState::StepHold;
                    } else if ovr <= 0.0 {
                        self.v_s = 0.0;
                        self.state = IplState::Paused;
                    } else {
                        self.plan_move_traj(ovr)?;
                        self.state = IplState::Running;
                    }
                    return Ok(());
                }
            }
        }
    }

    /// Plan the jerk-limited s-profile for the current move from the current
    /// state, honoring the override.
    fn plan_move_traj(&mut self, ovr: f64) -> Result<(), CncError> {
        let seg = self.current_plan().clone();
        let (src_line, obj_no) = {
            let mv = self
                .current_move()
                .expect("plan_move_traj called off a move element");
            (mv.src_line, mv.obj_no)
        };
        self.last_src_line = src_line;
        self.last_obj_no = obj_no;

        let v_max = seg.v_cap * ovr;
        // Exit velocity: the planned junction velocity, clamped to the current
        // cruise cap (rsruckig requires target ≤ max) and to what is actually
        // reachable in the remaining distance (prevents the time-optimal
        // profile from backing up to get a run-up).
        let remaining = (seg.length - self.s_local).max(0.0);
        let a_eff = self.limits.max_acceleration * self.lookahead.accel_margin;
        let reachable = (self.v_s * self.v_s + 2.0 * a_eff * remaining).sqrt();
        let mut v_exit = seg.v_exit.min(v_max).min(reachable);
        if self.single_step {
            v_exit = 0.0;
        }

        self.input.control_interface = ControlInterface::Position;
        self.input.current_position[0] = self.s_local;
        self.input.current_velocity[0] = self.v_s;
        self.input.current_acceleration[0] = self.a_s;
        self.input.target_position[0] = seg.length;
        self.input.target_velocity[0] = v_exit;
        self.input.target_acceleration[0] = 0.0;
        self.input.max_velocity[0] = v_max.max(v_exit);
        self.input.max_acceleration[0] = self.limits.max_acceleration;
        self.input.max_jerk[0] = self.limits.max_jerk;

        self.calculate(src_line)?;
        self.traj_override = ovr;
        self.planned_v_exit = v_exit;
        Ok(())
    }

    /// Plan an immediate jerk-limited stop from the current state
    /// (velocity control interface; position is unconstrained).
    fn plan_stop_traj(&mut self) -> Result<(), CncError> {
        let src_line = self.last_src_line;
        self.input.control_interface = ControlInterface::Velocity;
        self.input.current_position[0] = self.s_local;
        self.input.current_velocity[0] = self.v_s;
        self.input.current_acceleration[0] = self.a_s;
        self.input.target_velocity[0] = 0.0;
        self.input.target_acceleration[0] = 0.0;
        self.input.max_acceleration[0] = self.limits.max_acceleration;
        self.input.max_jerk[0] = self.limits.max_jerk;
        self.stop_s_offset = 0.0;
        self.calculate(src_line)
    }

    fn calculate(&mut self, src_line: usize) -> Result<(), CncError> {
        match self.otg.calculate(&self.input, &mut self.traj) {
            Ok(RuckigResult::Working) | Ok(RuckigResult::Finished) => {
                self.traj_time = 0.0;
                Ok(())
            }
            Ok(other) => Err(CncError::Otg {
                line: src_line,
                message: format!("trajectory calculation failed: {other:?}"),
            }),
            Err(e) => Err(CncError::Otg {
                line: src_line,
                message: e.to_string(),
            }),
        }
    }

    fn sample_traj(&mut self) -> (f64, f64, f64) {
        let mut pos = daov_stack![0.0];
        let mut vel = daov_stack![0.0];
        let mut acc = daov_stack![0.0];
        self.traj.at_time(
            self.traj_time,
            &mut Some(&mut pos),
            &mut Some(&mut vel),
            &mut Some(&mut acc),
            &mut None,
            &mut None,
        );
        (pos[0], vel[0], acc[0])
    }

    fn step_running(&mut self, ovr: f64) -> Result<(), CncError> {
        let mut t = self.traj_time + self.cycle_time;
        loop {
            let duration = self.traj.get_duration();
            if t < duration {
                break;
            }
            // Segment complete: snap to its exact end state
            t -= duration;
            let seg = self.current_plan().clone();
            self.s_local = seg.length;
            self.v_s = self.planned_v_exit;
            self.a_s = 0.0;
            self.update_pose();
            self.s_done += seg.length;
            self.cursor += 1;
            self.enter_next(ovr)?;
            if self.state != IplState::Running {
                // Dwell / hold / pause / finished: the leftover cycle time is
                // absorbed by that state (bounded by one cycle).
                return Ok(());
            }
        }
        self.traj_time = t;
        let (s, v, a) = self.sample_traj();
        let seg_len = self.current_plan().length;
        // Monotonicity guard: never move backward along the path
        self.s_local = s.clamp(self.s_local, seg_len);
        self.v_s = v.max(0.0);
        self.a_s = a;
        self.update_pose();
        Ok(())
    }

    fn step_pausing(&mut self) -> Result<(), CncError> {
        let duration = self.traj.get_duration();
        self.traj_time = (self.traj_time + self.cycle_time).min(duration);
        let (s_raw, v, a) = self.sample_traj();
        // The stop trajectory runs in the coordinates of the segment it was
        // planned in; stop_s_offset rebases samples after boundary crossings.
        let mut s = (s_raw - self.stop_s_offset).max(self.s_local);
        self.v_s = v.max(0.0);
        self.a_s = a;

        // The stop profile may run past the current segment's end when the
        // junction there was a blend: walk forward into following moves.
        loop {
            let seg_len = self.current_plan().length;
            if s <= seg_len {
                break;
            }
            let next_is_adjacent_move = matches!(
                self.queue.get(self.cursor + 1),
                Some(GeoElem::Move(_))
            );
            if !next_is_adjacent_move {
                // Should not happen (v_exit = 0 before non-move elements
                // guarantees the stop fits), but never leave the segment.
                s = seg_len;
                break;
            }
            s -= seg_len;
            self.stop_s_offset += seg_len;
            self.s_done += seg_len;
            self.cursor += 1;
            self.plan_pos += 1;
        }
        self.s_local = s;
        self.update_pose();

        if self.traj_time >= duration || self.v_s <= EPS_V {
            self.v_s = 0.0;
            self.a_s = 0.0;
            self.state = IplState::Paused;
        }
        Ok(())
    }

    /// Update path point, tangent and aux values from `s_local`.
    fn update_pose(&mut self) {
        let v_s = self.v_s;
        let s_local = self.s_local;
        let Some(mv) = self.current_or_last_move() else {
            return;
        };
        let param_len = mv.param_length();
        let s = s_local.clamp(0.0, param_len);
        let geo_len = mv.geo.length();
        let s_geo = s.min(geo_len);
        let point = mv.geo.point_at(s_geo);
        let tangent = if geo_len > 0.0 {
            mv.geo.tangent_at(s_geo)
        } else {
            [0.0; 3]
        };
        let u = if param_len > 0.0 { s / param_len } else { 1.0 };
        let n_aux = mv.aux_start.len();
        let mut aux_now = vec![0.0; n_aux];
        let mut aux_vel_now = vec![0.0; n_aux];
        for i in 0..n_aux {
            let delta = mv.aux_end[i] - mv.aux_start[i];
            aux_now[i] = mv.aux_start[i] + delta * u;
            aux_vel_now[i] = if param_len > 0.0 {
                delta / param_len * v_s
            } else {
                0.0
            };
        }
        self.point = point;
        self.tangent = tangent;
        self.aux_now = aux_now;
        self.aux_vel_now = aux_vel_now;
    }

    fn current_or_last_move(&self) -> Option<&GeoMove> {
        if let Some(GeoElem::Move(m)) = self.queue.get(self.cursor) {
            return Some(m);
        }
        // After the last move (finished / dwell): the previous move
        self.queue[..self.cursor.min(self.queue.len())]
            .iter()
            .rev()
            .find_map(|e| match e {
                GeoElem::Move(m) => Some(m),
                _ => None,
            })
    }

    fn make_output(&mut self) -> IplOutput {
        IplOutput {
            state: self.state,
            path_position: self.point,
            path_tangent: self.tangent,
            path_velocity: self.v_s,
            path_acceleration: self.a_s,
            aux: self.aux_now.clone(),
            aux_velocity: self.aux_vel_now.clone(),
            events: core::mem::take(&mut self.pending_events),
            src_line: self.last_src_line,
            obj_no: self.last_obj_no,
            s_total: self.s_done + self.s_local,
            progress: if self.total_length > 0.0 {
                ((self.s_done + self.s_local) / self.total_length).min(1.0)
            } else {
                1.0
            },
        }
    }
}
